const e={gongyong:{zijinmima:"Transaktionspasswort"},yonghu:{zijinmimashezhi:"Transaktionspasswort-Einstellung",tiaoguozijinmimajixuzhuce:"Das Überspringen der Transaktionspasswort-Einstellung setzt die Registrierung fort",xiugaizijinmima:"Transaktionspasswort ändern"},yingshe:{miaoheyue:"Optionshandel",miaoheyuejiaoyi:"Optionshandel",dazongshangpin:"Futures-Handel",dazongjiaoyidingdan:"Futures-Handelsauftrag",dazongzhanghu:"Futures-Handelskonto",dazongzichan:"Futures-Handelsvermögen",dazongyue:"Futures-Handelsguthaben",dazongshangpinjiaoyi:"Futures-Handel"},cbot455:{guizeshouce:"Regelhandbuch",jianguanzhiyan:"Regulatorische Richtlinien",guanyuwomen:"Über uns",tiyanhuihuang:"ERLEBE DEN GLANZ VON",huangjinqihuo:"Gold-Futures",quantianhoujiayi:"Handeln Sie rund um die Uhr auf Märkten, die nie schlafen",fengxianjiyubingcun:"WO RISIKO AUF CHANCE TRIFFT.",zhaodaochanpin:"Finden Sie das richtige Gold-Futures-Produkt für sich",tansuochanpin:"Entdecken Sie unsere Goldprodukte, um Ihr ideales Angebot in den weltweit aktivsten Goldderivatemärkten zu finden, die von Einzelpersonen und Institutionen weltweit genutzt werden und 23 Stunden am Tag gehandelt werden.",zuigao24h:"24h Hoch",zuidi24h:"24h Tief",chengjiaoliang24h:"24h Volumen",tianjiazixuan:"+ BEOBACHTUNGSLISTE",yichuzixuan:"- BEOBACHTUNGSLISTE",lijijiaoyi:"JETZT HANDELN",jiesuojihui:"Entsperren Sie eine Welt voller Möglichkeiten",jiarudingjianjiaoyizhe:"Schließe dich den Top-Händlern an, die bereits die Kraft von Futures und Optionen entdeckt haben. Durch die Erstellung eines CBOT-Handelskontos erhältst du kostenlosen Zugang zu hochwertigen Schulungsressourcen, Marktanalysen und modernsten Tools.",kaishijiayi:"HANDEL STARTEN",chuangjianzhanghu:"KONTO ERSTELLEN",shijiahuangjin:"Testen Sie Gold-Futures",shijiahuangjinmiaoshu:"Verbessern Sie Ihre Goldhandelsfähigkeiten und entdecken Sie neue Chancen mit realen Marktdaten in unserem risikofreien Handelssimulator.",kaishilianxi:"JETZT ÜBEN",texingyoushi:"Funktionen und Vorteile",lingxianliudongxing:"Führende Liquidität",lingxianliudongxingmiaoshu:"Mit durchschnittlich über 200.000 täglich gehandelten Kontrakten und einem offenen Interesse von über 900.000 können Sie Positionen problemlos eröffnen und schließen.",linghuozhixing:"Flexible Handelsausführung",linghuozhixingmiaoshu:"Greifen Sie über das zentrale Orderbuch, Block Trades oder RFQ auf Liquidität zu.",anquanbaozhang:"Sicherheit und Schutz",anquanbaozhangmiaoshu:"Reduzieren Sie das Gegenparteirisiko in einem zentral abgewickelten, von der CFTC regulierten Markt.",geyefangwen:"Elektronischer Zugang über Nacht",geyefangwenmiaoshu:"Verwalten Sie Positionen während der Geschäftszeiten in EMEA und APAC, wenn weltbewegende Nachrichten eintreffen.",qihuoganggan:"Futures-Hebelwirkung",qihuogangganmiaoshu:"Kontrollieren Sie einen größeren Nominalwert mit einem relativ kleinen Betrag, um Ihre Kaufkraft zu erhöhen.",jiarutiaozhang:"Verwandle Neugier in Vertrauen</br>Verwandle Unsicherheit in Handeln</br>Beginne den Weg zum Reichtum",lijizhuce:"JETZT REGISTRIEREN",wuyulunbijiaoyiliang:"Unvergleichliche tägliche Volumina bedeuten branchenführende Liquidität",zhaodaoliudongxing:"Finden Sie die Liquidität, um Ihre Handelsstrategien effizient auszuführen – wann und wie Sie wollen.",lianxiwomen:"Kontaktieren Sie uns",yazhouzongbu:"Asien-Hauptsitz",cmejituan:"CBOT Gruppe",dianhua:"Telefon",youxiang:"E-Mail",richengjiaoliang:"Tägliches Volumen und offene Positionen",zuihougengxin:"Zuletzt aktualisiert",suoyoushuju:"Alle Zahlen in Millionen.",jiaoyiriqi:"HANDELSDATUM",zongji:"GESAMT",cmeglobex:"CBOT GLOBEX",cmeclearport:"CBOT CLEARPORT",gongkaihanjia:"OPEN OUTCRY",chicang:"OFFENE POSITIONEN",richengjiao:"Tägliches Volumen",chicangliang:"Offene Positionen",mran_biaoti:"Aktuelle Marktregulierungsmitteilungen (MRANs)",mran_jianjie:"Seit der Gründung der CME Group durch die Fusion von CME und CBOT im Jahr 2007 und der anschließenden Fusion mit NYMEX/COMEX im Jahr 2008 hat die Marktregulierungsabteilung eine Reihe von Marktregulierungsmitteilungen (MRANs) herausgegeben, um Leitlinien zu den Regeln bereitzustellen. Die aktuellen MRANs sind unten nach den jeweils relevanten Börsen gruppiert aufgeführt.",mran_lianxi:"Bei Fragen zu den unten aufgeführten MRANs wenden Sie sich bitte per E-Mail an die Marktregulierungsabteilung unter {email}.",mran_huoqv:"Um eine Kopie früher veröffentlichter MRANs oder anderer Mitteilungen der CME Group zu erhalten, verwenden Sie bitte die Suchfunktion für Mitteilungen.",cme_intro:"Als der weltweit führende Derivatemarkt ist die CME Group der Ort, an dem die Welt Risiken managt. Wir ermöglichen es Kunden, Futures, Optionen, Kassamärkte und OTC-Märkte zu handeln, Portfolios zu optimieren und Daten zu analysieren – und befähigen so Marktteilnehmer weltweit, Risiken effizient zu steuern und Chancen zu nutzen. Die CME Group-Börsen bieten die breiteste Palette globaler Benchmark-Produkte über alle wichtigen Anlageklassen hinweg, basierend auf Zinssätzen, Aktienindizes, Devisen, Energie, Agrarprodukten und Metallen. Wir begegnen Unsicherheit und Volatilität mit Selbstvertrauen und Klarheit über den gesamten Handelszyklus und weltweit.",cme_motto:"Handeln, handeln, wachsen, investieren.",cme_description:"In einem globalen Umfeld voller Veränderungen bietet die CME Group innovative Produkte und Datensätze über alle wichtigen Anlageklassen hinweg, um Einzelpersonen und Institutionen zu helfen, ihre Handelsstrategien zu verbessern. Weitere Informationen finden Sie in diesem Video.",exchange_rules_title:"Börsenspezifische Regeln für CME, CBOT, NYMEX und COMEX",exchange_rules_description:"CME, CBOT, NYMEX und COMEX sind unabhängige Börsen, von denen jede ein separates, bei der CFTC registriertes Designated Contract Market mit Selbstregulierungsverantwortung bleibt und ihr eigenes Regelwerk pflegt. Um den Marktteilnehmern einen einheitlichen regulatorischen Rahmen zu bieten, wurden die Regelwerke weitgehend harmonisiert, sodass die Regeln soweit möglich in Struktur, Nummerierung und Sprache parallelisiert sind.",cme_footer_desc:"Chicago Board of Trade (CBOT)<br><br>Gründung und Geschichte: Gegründet im Jahr 1848 von 82 Getreidehändlern mit dem Ziel, den Getreidehandel zu regulieren. Im Jahr 1865 führte sie standardisierte Terminverträge und ein Margensystem ein, wodurch das Fundament des modernen Terminhandels gelegt wurde.<br><br>Hauptprodukte: Mit einer langen Geschichte ist sie eine der weltweit repräsentativsten Agrarbörsen und handelt hauptsächlich mit Terminkontrakten auf Mais, Sojabohnen und Weizen.<br><br>Elektronische Transformation: CBOT hat den Übergang vom traditionellen Parketthandel vollständig zur elektronischen Handelsplattform vollzogen und 2015 den Großteil des Parketthandels eingestellt.",server724:"24/7 Menschlicher Kundenservice",quanqiuzongbu:"Weltweite Zentrale",zhijiage:"Chicago",rengongfuwutishi:"Um Ihre wertvolle Zeit zu sparen und die Sicherheit Ihrer Gelder zu gewährleisten, bieten wir einen exklusiven 7x24-Stunden-Personaldienst an.",nongchanpin:"Agrarprodukte",nengyuan:"Energie",jinshu:"Metalle",nongchanpinshuoming:"Hedgen Sie Ihr Preisrisiko auf dem wachsenden globalen Agrarmarkt mit Benchmark-Produkten – Weizen-, Mais- und Sojabohnen-Futures und -Optionen. Finden Sie neue Chancen, um ereignisgesteuerte Trades präzise mit liquiden, aktiv gehandelten Agrarverträgen auszuführen.",nengyuanshuoming:"Erhalten Sie präzise Echtzeitpreise für die gefragtesten Energiemärkte. Handeln Sie Benchmark-Produkte – WTI-Rohöl, Henry-Hub-Erdgas, Brent-Rohöl und RBOB-Benzin – die weltweit zur Preisbildung und zum Risikomanagement verwendet werden.",jinshushuoming:"Drücken Sie Ihre Sicht auf die Metall-Forward-Kurve aus. Handeln Sie Intermarkt-Metallspreads oder entdecken Sie unsere breite Produktpalette – von standardisierten Benchmark- bis zu kleineren Kontrakten – um Ihrem Metallportfolio mehr Präzision zu verleihen."},zichan:{jiamihuobichongzhi:"Kryptowährungseinzahlung",jiamihuobitixian:"Kryptowährungsabhebung",yinhangkachongzhi:"Geld einzahlen",yinhangkatixian:"Geld abheben"}};export{e as default};
